import{_ as e,c as a,o as t,a4 as o}from"./chunks/framework.CpVK_f0P.js";const b=JSON.parse('{"title":"通用对话语言块","description":"","frontmatter":{},"headers":[],"relativePath":"expressions/conversation.md","filePath":"expressions/conversation.md"}'),i={name:"expressions/conversation.md"},l=o('<h1 id="通用对话语言块" tabindex="-1">通用对话语言块 <a class="header-anchor" href="#通用对话语言块" aria-label="Permalink to &quot;通用对话语言块&quot;">​</a></h1><h2 id="寒暄和近况" tabindex="-1">寒暄和近况 <a class="header-anchor" href="#寒暄和近况" aria-label="Permalink to &quot;寒暄和近况&quot;">​</a></h2><h3 id="_1-how-s-it-going" tabindex="-1">1. <code>How&#39;s it going?</code> <a class="header-anchor" href="#_1-how-s-it-going" aria-label="Permalink to &quot;1. `How&#39;s it going?`&quot;">​</a></h3><p>用于轻松地询问对方近况。</p><ul><li>Hey, how&#39;s it going?</li><li>How&#39;s it going at your new job?</li><li>I haven&#39;t seen you in a while. How&#39;s it going?</li></ul><h3 id="_2-what-have-you-been-up-to" tabindex="-1">2. <code>What have you been up to?</code> <a class="header-anchor" href="#_2-what-have-you-been-up-to" aria-label="Permalink to &quot;2. `What have you been up to?`&quot;">​</a></h3><p>用于询问对方最近在忙什么、做了什么。</p><ul><li>What have you been up to lately?</li><li>I haven&#39;t seen you in months. What have you been up to?</li><li>What have you been up to since you changed jobs?</li></ul><h3 id="_3-how-was" tabindex="-1">3. <code>How was ...?</code> <a class="header-anchor" href="#_3-how-was" aria-label="Permalink to &quot;3. `How was ...?`&quot;">​</a></h3><p>用于询问某次活动或一段经历怎么样。</p><ul><li>How was your weekend?</li><li>How was work today?</li><li>How was your trip to Shanghai?</li></ul><h3 id="_4-it-s-been-a-while" tabindex="-1">4. <code>It&#39;s been a while.</code> <a class="header-anchor" href="#_4-it-s-been-a-while" aria-label="Permalink to &quot;4. `It&#39;s been a while.`&quot;">​</a></h3><p>表示“好久不见、已经有一段时间了”。</p><ul><li>It&#39;s been a while. How have you been?</li><li>It&#39;s been a while since we last talked.</li><li>It&#39;s been a while since I visited this place.</li></ul><h2 id="邀请、安排和改期" tabindex="-1">邀请、安排和改期 <a class="header-anchor" href="#邀请、安排和改期" aria-label="Permalink to &quot;邀请、安排和改期&quot;">​</a></h2><h3 id="_5-are-you-free" tabindex="-1">5. <code>Are you free ...?</code> <a class="header-anchor" href="#_5-are-you-free" aria-label="Permalink to &quot;5. `Are you free ...?`&quot;">​</a></h3><p>用于询问对方某个时间是否有空。</p><ul><li>Are you free this weekend?</li><li>Are you free for lunch tomorrow?</li><li>Are you free after work?</li></ul><h3 id="_6-would-you-like-to" tabindex="-1">6. <code>Would you like to ...?</code> <a class="header-anchor" href="#_6-would-you-like-to" aria-label="Permalink to &quot;6. `Would you like to ...?`&quot;">​</a></h3><p>用于礼貌地邀请对方做某事。</p><ul><li>Would you like to join us for dinner?</li><li>Would you like to get some coffee?</li><li>Would you like to come over this weekend?</li></ul><h3 id="_7-can-we-move-it-to" tabindex="-1">7. <code>Can we move it to ...?</code> <a class="header-anchor" href="#_7-can-we-move-it-to" aria-label="Permalink to &quot;7. `Can we move it to ...?`&quot;">​</a></h3><p>用于请求把已经安排好的事情改到另一个时间。</p><ul><li>Can we move it to Friday?</li><li>Can we move it to tomorrow morning?</li><li>Can we move it to sometime next week?</li></ul><h3 id="_8-something-came-up" tabindex="-1">8. <code>Something came up.</code> <a class="header-anchor" href="#_8-something-came-up" aria-label="Permalink to &quot;8. `Something came up.`&quot;">​</a></h3><p>表示临时发生了意外情况，因此需要改变原来的安排。</p><ul><li>Something came up, so I can&#39;t make it tonight.</li><li>I&#39;m sorry, but something came up at work.</li><li>Something came up. Can we meet another day?</li></ul><h3 id="_9-maybe-another-time" tabindex="-1">9. <code>Maybe another time.</code> <a class="header-anchor" href="#_9-maybe-another-time" aria-label="Permalink to &quot;9. `Maybe another time.`&quot;">​</a></h3><p>用于委婉地拒绝邀请，同时保留以后再约的可能。</p><ul><li>I can&#39;t make it tonight. Maybe another time.</li><li>I&#39;m really busy this week, but maybe another time.</li><li>Thanks for asking. Maybe another time.</li></ul><h2 id="同意、选择和拒绝" tabindex="-1">同意、选择和拒绝 <a class="header-anchor" href="#同意、选择和拒绝" aria-label="Permalink to &quot;同意、选择和拒绝&quot;">​</a></h2><h3 id="_10-i-completely-agree" tabindex="-1">10. <code>I completely agree.</code> <a class="header-anchor" href="#_10-i-completely-agree" aria-label="Permalink to &quot;10. `I completely agree.`&quot;">​</a></h3><p>用于明确表示完全同意。</p><ul><li>I completely agree with you.</li><li>I completely agree that we need more time.</li><li>That&#39;s exactly how I see it. I completely agree.</li></ul><h3 id="_11-that-s-a-good-point" tabindex="-1">11. <code>That&#39;s a good point.</code> <a class="header-anchor" href="#_11-that-s-a-good-point" aria-label="Permalink to &quot;11. `That&#39;s a good point.`&quot;">​</a></h3><p>用于认可对方提出的观点。</p><ul><li>That&#39;s a good point. I hadn&#39;t thought about that.</li><li>That&#39;s a good point about the cost.</li><li>You&#39;re right. That&#39;s a good point.</li></ul><h3 id="_12-i-m-not-sure-about" tabindex="-1">12. <code>I&#39;m not sure about ...</code> <a class="header-anchor" href="#_12-i-m-not-sure-about" aria-label="Permalink to &quot;12. `I&#39;m not sure about ...`&quot;">​</a></h3><p>用于表达不确定、保留意见或轻微反对。</p><ul><li>I&#39;m not sure about that idea.</li><li>I&#39;m not sure about changing the plan now.</li><li>I&#39;m not sure about the timing.</li></ul><h3 id="_13-i-m-afraid-i-can-t" tabindex="-1">13. <code>I&#39;m afraid I can&#39;t ...</code> <a class="header-anchor" href="#_13-i-m-afraid-i-can-t" aria-label="Permalink to &quot;13. `I&#39;m afraid I can&#39;t ...`&quot;">​</a></h3><p>用于礼貌地拒绝请求或邀请。</p><ul><li>I&#39;m afraid I can&#39;t make it tonight.</li><li>I&#39;m afraid I can&#39;t help you with that.</li><li>I&#39;m afraid I can&#39;t stay very long.</li></ul><h3 id="_14-i-d-rather" tabindex="-1">14. <code>I&#39;d rather ...</code> <a class="header-anchor" href="#_14-i-d-rather" aria-label="Permalink to &quot;14. `I&#39;d rather ...`&quot;">​</a></h3><p>用于表达自己更愿意选择什么，后接动词原形。</p><ul><li>I&#39;d rather stay home tonight.</li><li>I&#39;d rather talk about it in person.</li><li>I&#39;d rather wait until we have more information.</li></ul><h3 id="_15-either-one-is-fine-with-me" tabindex="-1">15. <code>Either one is fine with me.</code> <a class="header-anchor" href="#_15-either-one-is-fine-with-me" aria-label="Permalink to &quot;15. `Either one is fine with me.`&quot;">​</a></h3><p>表示两个选择自己都可以接受。</p><ul><li>Morning or afternoon? Either one is fine with me.</li><li>We can take the bus or the subway. Either one is fine with me.</li><li>We can eat here or somewhere else. Either one is fine with me.</li></ul><h2 id="接话、打断和听不清" tabindex="-1">接话、打断和听不清 <a class="header-anchor" href="#接话、打断和听不清" aria-label="Permalink to &quot;接话、打断和听不清&quot;">​</a></h2><h3 id="_16-can-i-add-something" tabindex="-1">16. <code>Can I add something?</code> <a class="header-anchor" href="#_16-can-i-add-something" aria-label="Permalink to &quot;16. `Can I add something?`&quot;">​</a></h3><p>用于礼貌地加入对话或补充观点。</p><ul><li>Can I add something?</li><li>Can I add something to what you just said?</li><li>Before we move on, can I add something?</li></ul><h3 id="_17-sorry-to-interrupt-but" tabindex="-1">17. <code>Sorry to interrupt, but ...</code> <a class="header-anchor" href="#_17-sorry-to-interrupt-but" aria-label="Permalink to &quot;17. `Sorry to interrupt, but ...`&quot;">​</a></h3><p>用于不得不打断对方时先表示礼貌。</p><ul><li>Sorry to interrupt, but I have a quick question.</li><li>Sorry to interrupt, but we&#39;re running out of time.</li><li>Sorry to interrupt, but I think I missed something.</li></ul><h3 id="_18-go-ahead" tabindex="-1">18. <code>Go ahead.</code> <a class="header-anchor" href="#_18-go-ahead" aria-label="Permalink to &quot;18. `Go ahead.`&quot;">​</a></h3><p>用于请对方继续说、先说或先做。</p><ul><li>You wanted to say something? Go ahead.</li><li>Go ahead. I&#39;m listening.</li><li>If you have a question, go ahead.</li></ul><h3 id="_19-could-you-say-that-again" tabindex="-1">19. <code>Could you say that again?</code> <a class="header-anchor" href="#_19-could-you-say-that-again" aria-label="Permalink to &quot;19. `Could you say that again?`&quot;">​</a></h3><p>用于请对方重复刚才的话。</p><ul><li>Sorry, could you say that again?</li><li>I didn&#39;t catch the last part. Could you say that again?</li><li>Could you say that again a little more slowly?</li></ul><h3 id="_20-could-you-speak-a-little-more-slowly" tabindex="-1">20. <code>Could you speak a little more slowly?</code> <a class="header-anchor" href="#_20-could-you-speak-a-little-more-slowly" aria-label="Permalink to &quot;20. `Could you speak a little more slowly?`&quot;">​</a></h3><p>用于请对方放慢语速。</p><ul><li>Could you speak a little more slowly?</li><li>I&#39;m still learning English. Could you speak a little more slowly?</li><li>Sorry, could you speak a little more slowly this time?</li></ul><h3 id="_21-let-me-think-about-that" tabindex="-1">21. <code>Let me think about that.</code> <a class="header-anchor" href="#_21-let-me-think-about-that" aria-label="Permalink to &quot;21. `Let me think about that.`&quot;">​</a></h3><p>用于在回答问题前争取思考时间。</p><ul><li>Let me think about that for a second.</li><li>That&#39;s an interesting question. Let me think about that.</li><li>Let me think about that before I give you an answer.</li></ul><h2 id="说明原因、比较和结果" tabindex="-1">说明原因、比较和结果 <a class="header-anchor" href="#说明原因、比较和结果" aria-label="Permalink to &quot;说明原因、比较和结果&quot;">​</a></h2><h3 id="_22-the-main-reason-is" tabindex="-1">22. <code>The main reason is ...</code> <a class="header-anchor" href="#_22-the-main-reason-is" aria-label="Permalink to &quot;22. `The main reason is ...`&quot;">​</a></h3><p>用于直接说明最主要的原因。</p><ul><li>The main reason is the cost.</li><li>The main reason I left early was that I felt sick.</li><li>The main reason we chose this option is its simplicity.</li></ul><h3 id="_23-that-s-why" tabindex="-1">23. <code>That&#39;s why ...</code> <a class="header-anchor" href="#_23-that-s-why" aria-label="Permalink to &quot;23. `That&#39;s why ...`&quot;">​</a></h3><p>用于说明前面的情况导致了什么结果。</p><ul><li>I missed the bus. That&#39;s why I was late.</li><li>The store was closed. That&#39;s why I came back empty-handed.</li><li>We need more test data. That&#39;s why we haven&#39;t released it yet.</li></ul><h3 id="_24-the-difference-is-that" tabindex="-1">24. <code>The difference is that ...</code> <a class="header-anchor" href="#_24-the-difference-is-that" aria-label="Permalink to &quot;24. `The difference is that ...`&quot;">​</a></h3><p>用于说明两件事之间最重要的区别。</p><ul><li>The difference is that this one is cheaper.</li><li>The difference is that the old version works offline.</li><li>The difference is that she works from home.</li></ul><h3 id="_25-compared-with" tabindex="-1">25. <code>Compared with ..., ...</code> <a class="header-anchor" href="#_25-compared-with" aria-label="Permalink to &quot;25. `Compared with ..., ...`&quot;">​</a></h3><p>用于比较两个人、事物或情况。</p><ul><li>Compared with last week, I feel much better.</li><li>Compared with the old version, this one is easier to use.</li><li>Compared with driving, taking the subway is more convenient.</li></ul><h3 id="_26-for-example" tabindex="-1">26. <code>For example, ...</code> <a class="header-anchor" href="#_26-for-example" aria-label="Permalink to &quot;26. `For example, ...`&quot;">​</a></h3><p>用于给前面的观点补充一个具体例子。</p><ul><li>Some tasks can be automated. For example, we can automate the tests.</li><li>I like outdoor activities. For example, I often go hiking.</li><li>There are several ways to get there. For example, you can take Line 2.</li></ul><h3 id="_27-in-other-words" tabindex="-1">27. <code>In other words, ...</code> <a class="header-anchor" href="#_27-in-other-words" aria-label="Permalink to &quot;27. `In other words, ...`&quot;">​</a></h3><p>用于换一种更清楚的方式重新说明。</p><ul><li>In other words, we need to start again.</li><li>In other words, the change only affects new users.</li><li>In other words, I won&#39;t be available until Monday.</li></ul><h3 id="_28-as-a-result" tabindex="-1">28. <code>As a result, ...</code> <a class="header-anchor" href="#_28-as-a-result" aria-label="Permalink to &quot;28. `As a result, ...`&quot;">​</a></h3><p>用于说明前面的事情造成的结果。</p><ul><li>The train was delayed. As a result, I arrived late.</li><li>We removed the extra request. As a result, the page loads faster.</li><li>He didn&#39;t sleep well. As a result, he felt tired all day.</li></ul><h2 id="总结和结束对话" tabindex="-1">总结和结束对话 <a class="header-anchor" href="#总结和结束对话" aria-label="Permalink to &quot;总结和结束对话&quot;">​</a></h2><h3 id="_29-so-basically" tabindex="-1">29. <code>So, basically, ...</code> <a class="header-anchor" href="#_29-so-basically" aria-label="Permalink to &quot;29. `So, basically, ...`&quot;">​</a></h3><p>用于用简单的话概括前面的内容，语气比较口语化。</p><ul><li>So, basically, we have two options.</li><li>So, basically, I need to do the whole thing again.</li><li>So, basically, nothing will change for current users.</li></ul><h3 id="_30-to-sum-up" tabindex="-1">30. <code>To sum up, ...</code> <a class="header-anchor" href="#_30-to-sum-up" aria-label="Permalink to &quot;30. `To sum up, ...`&quot;">​</a></h3><p>用于在较正式的说明或讨论中总结重点。</p><ul><li>To sum up, we need more time and better test data.</li><li>To sum up, the trip was tiring but enjoyable.</li><li>To sum up, both options have advantages and disadvantages.</li></ul><h3 id="_31-that-s-all-i-wanted-to-say" tabindex="-1">31. <code>That&#39;s all I wanted to say.</code> <a class="header-anchor" href="#_31-that-s-all-i-wanted-to-say" aria-label="Permalink to &quot;31. `That&#39;s all I wanted to say.`&quot;">​</a></h3><p>用于说明自己已经表达完毕。</p><ul><li>That&#39;s all I wanted to say about the issue.</li><li>I think I&#39;ve covered everything. That&#39;s all I wanted to say.</li><li>That&#39;s all I wanted to say for now.</li></ul><h3 id="_32-it-was-nice-talking-to-you" tabindex="-1">32. <code>It was nice talking to you.</code> <a class="header-anchor" href="#_32-it-was-nice-talking-to-you" aria-label="Permalink to &quot;32. `It was nice talking to you.`&quot;">​</a></h3><p>用于礼貌地结束一次谈话。</p><ul><li>It was nice talking to you.</li><li>It was nice talking to you after all this time.</li><li>I have to leave now, but it was nice talking to you.</li></ul><h3 id="_33-i-should-get-going" tabindex="-1">33. <code>I should get going.</code> <a class="header-anchor" href="#_33-i-should-get-going" aria-label="Permalink to &quot;33. `I should get going.`&quot;">​</a></h3><p>用于自然地表示自己该离开了。</p><ul><li>It&#39;s getting late. I should get going.</li><li>I have an early meeting tomorrow, so I should get going.</li><li>Thanks for dinner. I should get going.</li></ul><h3 id="_34-let-s-talk-again-soon" tabindex="-1">34. <code>Let&#39;s talk again soon.</code> <a class="header-anchor" href="#_34-let-s-talk-again-soon" aria-label="Permalink to &quot;34. `Let&#39;s talk again soon.`&quot;">​</a></h3><p>用于结束谈话时表示希望以后继续联系。</p><ul><li>It was great catching up. Let&#39;s talk again soon.</li><li>I have to go, but let&#39;s talk again soon.</li><li>Let me know how things go, and let&#39;s talk again soon.</li></ul>',109),h=[l];function r(n,s,d,u,c,m){return t(),a("div",null,h)}const w=e(i,[["render",r]]);export{b as __pageData,w as default};
